import{_ as r,l as i,o as e,c as s,v as o,p as n,x as t,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const F=JSON.parse('{"title":"栈帧布局与帧指针","description":"","frontmatter":{"title":"栈帧布局与帧指针","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-frame-layout.md","filePath":"cs/stack-frame-layout.md","lastUpdated":1789023840000}'),h={name:"cs/stack-frame-layout.md"};function m(_,a,u,P,f,A){const l=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=o('<h1 id="栈帧布局与帧指针" tabindex="-1">栈帧布局与帧指针 <a class="header-anchor" href="#栈帧布局与帧指针" aria-label="Permalink to &quot;栈帧布局与帧指针&quot;">​</a></h1><div class="epigraph"><p>帧里放溢出槽、alloca、保存的 callee-save、对齐填充。帧指针使动态大小与调试稳定；省略帧指针把基址改成栈指针相对，省一个寄存器。</p><footer>—— 据 System V ABI 栈布局；龙书 7.2；组成课栈约定整理</footer></div><p>上一课<a href="/cs/calling-convention-impl">调用约定实现</a>把参数放进槽或寄存器。缺口是<strong>整帧地图</strong>：偏移谁算、<code>FP</code> vs <code>SP</code> 寻址、red zone、可变 alloca。本课钉布局，展开表下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>静态槽：编译期定偏移，可用 <code>SP+k</code>（若帧大小固定）。VLA/<code>alloca</code>：大小运行时才知，常用 <code>FP</code> 指向固定区，动态区在另一侧。缺口是<strong>寻址基址选择</strong>，不是 ABI 分类。</p><p>省略 FP（<code>-fomit-frame-pointer</code>）：多一个 GPR，调试与 unwind 靠 DWARF 的 CFA 规则补偿。</p><h3 id="帧指针不是指令指针" tabindex="-1">帧指针不是指令指针 <a class="header-anchor" href="#帧指针不是指令指针" aria-label="Permalink to &quot;帧指针不是指令指针&quot;">​</a></h3><p><code>FP</code>/<code>rbp</code> 指向当前帧的固定锚。不要和 <code>PC</code> 混。</p><p><span class="marginnote">SysV 栈增长方向。x86-64 red zone。本课与组成课 calling-convention-stack 分工：那里是约定，这里是后端如何填。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分配器交出 spill 槽数量。算总大小、对齐。序言：保存 FP、移动 FP、减 SP。收尾逆序。 outgoing 参数区在调用前再减或预留。</p>',11)),(e(),n(p,null,{default:t(()=>[c(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEED%5B%22spill%20%2F%20alloca%20%2F%20save%22%5D%20--%3E%20LAY%5B%22%E5%AF%B9%E9%BD%90%E5%B8%83%E5%B1%80%22%5D%0A%20%20LAY%20--%3E%20FP%5B%22FP%20%E6%88%96%20SP%20%E7%9B%B8%E5%AF%B9%22%5D%0A%20%20FP%20--%3E%20PRO%5B%22%E5%BA%8F%E8%A8%80%20%2F%20%E6%94%B6%E5%B0%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>与尾调用：收尾可与 jmp 合并，帧必须能在跳前拆掉。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>安全：栈金丝雀在返回地址附近，布局要给 sanitizer 留位。不要把溢出槽和 incoming 参数重叠除非约定允许。</p><p>异步信号：red zone 可被信号踩，内核代码禁用。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CFI 指令全文。后课默认：帧有确定布局；可 omit FP。下一课栈展开与 unwind 表。</p><p>也不把帧当网络协议帧。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>帧布局：spill、保存寄存器、动态区、对齐。</li><li>FP 服务动态大小与调试；omit 省寄存器。</li><li>序言/收尾实现布局。</li><li>出处：System V ABI；Aho et al. 龙书 7.2。</li></ul>',9))])}const E=r(h,[["render",m]]);export{F as __pageData,E as default};
